   left,top,right,bottom=box;assert right>left and bottom>top,(i,target,crop)
   clipped=Image.new('RGB',(right-left,bottom-top),'white');inside=(max(0,left),max(0,top),min(w,right),min(h,bottom));clipped.paste(im.crop(inside),(max(0,-left),max(0,-top)));im=clipped
  if raw.suffix.lower() in ['.wmf','.emf']:
